-- Personnel sources remain independent from clinical permission and customer events.
CREATE TABLE staff_record_roots(id TEXT PRIMARY KEY,staff_id TEXT NOT NULL REFERENCES users(id),store_id TEXT NOT NULL REFERENCES stores(id),kind TEXT NOT NULL CHECK(kind IN('qualification','shift','absence','training')),serial INTEGER NOT NULL CHECK(serial>0),record_number TEXT NOT NULL,first_version_id TEXT NOT NULL UNIQUE REFERENCES staff_record_versions(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,record_number),FOREIGN KEY(first_version_id,id) REFERENCES staff_record_versions(id,root_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE staff_record_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES staff_record_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),event_id TEXT NOT NULL UNIQUE REFERENCES staff_record_events(id) DEFERRABLE INITIALLY DEFERRED,title TEXT NOT NULL,data_json TEXT NOT NULL CHECK(json_valid(data_json) AND json_type(data_json)='object'),source_reference TEXT NOT NULL,source_note TEXT NOT NULL,record_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version),UNIQUE(id,root_id),FOREIGN KEY(event_id,id) REFERENCES staff_record_events(id,version_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE staff_record_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES staff_record_roots(id),version_id TEXT NOT NULL REFERENCES staff_record_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('record','withdraw')),status TEXT NOT NULL CHECK(status IN('recorded','withdrawn')),reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,version_id));
CREATE VIEW staff_record_current AS SELECT * FROM staff_record_events e WHERE revision=(SELECT max(revision) FROM staff_record_events WHERE root_id=e.root_id);
CREATE TRIGGER staff_record_root_source BEFORE INSERT ON staff_record_roots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u WHERE u.id=NEW.staff_id AND u.store_id=NEW.store_id AND u.role<>'guardian') OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM staff_record_roots WHERE store_id=NEW.store_id),1) OR NEW.record_number IS NOT 'SR-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'staff record fixed store/employee/number') END;END;
CREATE TRIGGER staff_record_version_source BEFORE INSERT ON staff_record_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM staff_record_roots r JOIN users u ON u.id=r.staff_id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND u.store_id=r.store_id AND u.role<>'guardian') OR NEW.version<>coalesce((SELECT max(version)+1 FROM staff_record_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM staff_record_events WHERE store_id=NEW.store_id),0) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM staff_record_roots r WHERE r.id=NEW.root_id AND r.first_version_id=NEW.id AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by) THEN RAISE(ABORT,'staff record version/current source pairing') END;END;
CREATE TRIGGER staff_record_event_source BEFORE INSERT ON staff_record_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM staff_record_versions v WHERE v.id=NEW.version_id AND v.root_id=NEW.root_id AND v.store_id=NEW.store_id) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM staff_record_events WHERE store_id=NEW.store_id),1) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM staff_record_events WHERE root_id=NEW.root_id),1) OR NEW.action='record' AND (NEW.status<>'recorded' OR NOT EXISTS(SELECT 1 FROM staff_record_versions v WHERE v.id=NEW.version_id AND v.event_id=NEW.id AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.reason=NEW.reason AND v.version=coalesce((SELECT max(v2.version)+1 FROM staff_record_events x JOIN staff_record_versions v2 ON v2.id=x.version_id WHERE x.root_id=NEW.root_id),1))) THEN RAISE(ABORT,'staff record continuous paired event') END;
 SELECT CASE WHEN NEW.action='withdraw' AND (NEW.status<>'withdrawn' OR NOT EXISTS(SELECT 1 FROM staff_record_current e WHERE e.root_id=NEW.root_id AND e.status='recorded' AND e.version_id=NEW.version_id)) THEN RAISE(ABORT,'staff record explicit current withdrawal') END;END;
CREATE TRIGGER staff_record_typed_data BEFORE INSERT ON staff_record_versions WHEN NOT EXISTS(SELECT 1 FROM staff_record_roots r WHERE r.id=NEW.root_id AND ((r.kind='qualification' AND NEW.data_json=json_object('credential_label',json_extract(NEW.data_json,'$.credential_label'),'identifier_status',json_extract(NEW.data_json,'$.identifier_status'),'identifier',json_extract(NEW.data_json,'$.identifier'),'issuer_status',json_extract(NEW.data_json,'$.issuer_status'),'issuer_note',json_extract(NEW.data_json,'$.issuer_note'),'issued_status',json_extract(NEW.data_json,'$.issued_status'),'issued_date',json_extract(NEW.data_json,'$.issued_date'),'expiry_status',json_extract(NEW.data_json,'$.expiry_status'),'expiry_date',json_extract(NEW.data_json,'$.expiry_date'),'scope_note',json_extract(NEW.data_json,'$.scope_note')) AND (json_type(NEW.data_json,'$.credential_label') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.credential_label'))) BETWEEN 1 AND 300 AND length(json_extract(NEW.data_json,'$.credential_label'))<=300 AND instr(json_extract(NEW.data_json,'$.credential_label'),char(0))=0) AND (json_type(NEW.data_json,'$.scope_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.scope_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.scope_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.scope_note'),char(0))=0) AND ((json_extract(NEW.data_json,'$.identifier_status')='unknown' AND json_type(NEW.data_json,'$.identifier')='null' OR json_extract(NEW.data_json,'$.identifier_status')='recorded' AND (json_type(NEW.data_json,'$.identifier') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.identifier'))) BETWEEN 1 AND 300 AND length(json_extract(NEW.data_json,'$.identifier'))<=300 AND instr(json_extract(NEW.data_json,'$.identifier'),char(0))=0))) AND ((json_extract(NEW.data_json,'$.issuer_status')='unknown' AND json_type(NEW.data_json,'$.issuer_note')='null' OR json_extract(NEW.data_json,'$.issuer_status')='recorded' AND (json_type(NEW.data_json,'$.issuer_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.issuer_note'))) BETWEEN 1 AND 1000 AND length(json_extract(NEW.data_json,'$.issuer_note'))<=1000 AND instr(json_extract(NEW.data_json,'$.issuer_note'),char(0))=0))) AND ((json_extract(NEW.data_json,'$.issued_status')='unknown' AND json_type(NEW.data_json,'$.issued_date')='null' OR json_extract(NEW.data_json,'$.issued_status')='recorded' AND (length(json_extract(NEW.data_json,'$.issued_date'))=10 AND date(json_extract(NEW.data_json,'$.issued_date'),'+0 days') IS json_extract(NEW.data_json,'$.issued_date') AND json_extract(NEW.data_json,'$.issued_date')<=substr(NEW.created_at,1,10)))) AND ((json_extract(NEW.data_json,'$.expiry_status')='unknown' AND json_type(NEW.data_json,'$.expiry_date')='null' OR json_extract(NEW.data_json,'$.expiry_status')='recorded' AND (length(json_extract(NEW.data_json,'$.expiry_date'))=10 AND date(json_extract(NEW.data_json,'$.expiry_date'),'+0 days') IS json_extract(NEW.data_json,'$.expiry_date'))))) OR (r.kind='shift' AND NEW.data_json=json_object('starts_at',json_extract(NEW.data_json,'$.starts_at'),'ends_at',json_extract(NEW.data_json,'$.ends_at'),'place_note',json_extract(NEW.data_json,'$.place_note'),'duty_note',json_extract(NEW.data_json,'$.duty_note')) AND (length(json_extract(NEW.data_json,'$.starts_at'))=24 AND strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(NEW.data_json,'$.starts_at')) IS json_extract(NEW.data_json,'$.starts_at')) AND (length(json_extract(NEW.data_json,'$.ends_at'))=24 AND strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(NEW.data_json,'$.ends_at')) IS json_extract(NEW.data_json,'$.ends_at')) AND (json_extract(NEW.data_json,'$.ends_at')>json_extract(NEW.data_json,'$.starts_at')) AND (json_type(NEW.data_json,'$.place_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.place_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.place_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.place_note'),char(0))=0) AND (json_type(NEW.data_json,'$.duty_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.duty_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.duty_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.duty_note'),char(0))=0)) OR (r.kind='absence' AND NEW.data_json=json_object('starts_at',json_extract(NEW.data_json,'$.starts_at'),'ends_at',json_extract(NEW.data_json,'$.ends_at'),'absence_note',json_extract(NEW.data_json,'$.absence_note'),'coverage_note',json_extract(NEW.data_json,'$.coverage_note')) AND (length(json_extract(NEW.data_json,'$.starts_at'))=24 AND strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(NEW.data_json,'$.starts_at')) IS json_extract(NEW.data_json,'$.starts_at')) AND (length(json_extract(NEW.data_json,'$.ends_at'))=24 AND strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(NEW.data_json,'$.ends_at')) IS json_extract(NEW.data_json,'$.ends_at')) AND (json_extract(NEW.data_json,'$.ends_at')>json_extract(NEW.data_json,'$.starts_at')) AND (json_type(NEW.data_json,'$.absence_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.absence_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.absence_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.absence_note'),char(0))=0) AND (json_type(NEW.data_json,'$.coverage_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.coverage_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.coverage_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.coverage_note'),char(0))=0)) OR (r.kind='training' AND NEW.data_json=json_object('time_status',json_extract(NEW.data_json,'$.time_status'),'occurred_at',json_extract(NEW.data_json,'$.occurred_at'),'training_label',json_extract(NEW.data_json,'$.training_label'),'participation_status',json_extract(NEW.data_json,'$.participation_status'),'outcome_note',json_extract(NEW.data_json,'$.outcome_note')) AND ((json_extract(NEW.data_json,'$.time_status')='unknown' AND json_type(NEW.data_json,'$.occurred_at')='null' OR json_extract(NEW.data_json,'$.time_status')='recorded' AND (length(json_extract(NEW.data_json,'$.occurred_at'))=24 AND strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(NEW.data_json,'$.occurred_at')) IS json_extract(NEW.data_json,'$.occurred_at')) AND json_extract(NEW.data_json,'$.occurred_at')<=NEW.created_at)) AND (json_type(NEW.data_json,'$.training_label') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.training_label'))) BETWEEN 1 AND 300 AND length(json_extract(NEW.data_json,'$.training_label'))<=300 AND instr(json_extract(NEW.data_json,'$.training_label'),char(0))=0) AND (json_extract(NEW.data_json,'$.participation_status') IN('not_recorded','attended','completed')) AND (json_type(NEW.data_json,'$.outcome_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.outcome_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.outcome_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.outcome_note'),char(0))=0)))) BEGIN SELECT RAISE(ABORT,'staff record explicit canonical typed source');END;
CREATE TRIGGER staff_record_roots_actor BEFORE INSERT ON staff_record_roots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM staff_record_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'staff record current actor/time');END;
CREATE TRIGGER staff_record_roots_no_update BEFORE UPDATE ON staff_record_roots BEGIN SELECT RAISE(ABORT,'staff record immutable');END;
CREATE TRIGGER staff_record_roots_no_delete BEFORE DELETE ON staff_record_roots BEGIN SELECT RAISE(ABORT,'staff record immutable');END;
CREATE TRIGGER staff_record_versions_actor BEFORE INSERT ON staff_record_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM staff_record_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'staff record current actor/time');END;
CREATE TRIGGER staff_record_versions_no_update BEFORE UPDATE ON staff_record_versions BEGIN SELECT RAISE(ABORT,'staff record immutable');END;
CREATE TRIGGER staff_record_versions_no_delete BEFORE DELETE ON staff_record_versions BEGIN SELECT RAISE(ABORT,'staff record immutable');END;
CREATE TRIGGER staff_record_events_actor BEFORE INSERT ON staff_record_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM staff_record_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'staff record current actor/time');END;
CREATE TRIGGER staff_record_events_no_update BEFORE UPDATE ON staff_record_events BEGIN SELECT RAISE(ABORT,'staff record immutable');END;
CREATE TRIGGER staff_record_events_no_delete BEFORE DELETE ON staff_record_events BEGIN SELECT RAISE(ABORT,'staff record immutable');END;
CREATE TRIGGER staff_record_versions_text BEFORE INSERT ON staff_record_versions WHEN length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR instr(NEW.source_reference,char(0))>0 OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR instr(NEW.source_note,char(0))>0 OR length(trim(NEW.record_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.record_note)>2000 OR instr(NEW.record_note,char(0))>0 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 BEGIN SELECT RAISE(ABORT,'staff record explicit source text');END;
CREATE TRIGGER staff_record_events_text BEFORE INSERT ON staff_record_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 OR instr(NEW.next_step,char(0))>0 BEGIN SELECT RAISE(ABORT,'staff record explicit source text');END;
